/* -- Clock（只读；无 authority 语义） -- */
/* 单调时钟（`rdtime` 的原始 tick）；频率见 [`kcore_timebase_hz`]。
 * 真机 timebase 常是 10 MHz（1 tick = 100 ns）——测很短的操作要累积多次。 */
uint64_t kcore_now(void);
/* 时钟频率（Hz），用于把 tick 换算成时间。 */
uint64_t kcore_timebase_hz(void);
/* -- Memory resource（域视图，无账本） -- */
/* 取一段内存 backing，返回本执行域访问窗口（kind = KCORE_MEMORY_VIEW_LOCAL_VA）：
 * min_len > 0、min_align 为非零 2 的幂；成功时 view.len >= min_len，首次交付零初始化。
 * 无账本：不发 id、不记 owner，view 自身就是身份（释放凭同一 view 走 kcore_memory_release）。
 * KernelNative 给共享 AS 的 VA；Isolated 给实例私有 VA；Sandboxed 直调返回 ENOTSUP。 */
int32_t kcore_memory_acquire(uint64_t min_len, uint64_t min_align, struct kcore_memory_view *out_view);
/* 交回一个 kcore_memory_acquire 交付的 view，把 backing 归还分配器。
 * KernelNative 受信操作；(base, len) 必须与 acquire 一致。
 * Isolated 按私有 AS 精确映射释放动态 backing，调用方保证无继续借用；不释放 image/stack。 */
int32_t kcore_memory_release(const struct kcore_memory_view *view);
/* -- KernelNative heap backend（KernelNative 部署后端；Isolated import 拒绝） -- */
/* KernelNative 部署后端：从 Core 共享堆分配（size / align 同 Rust GlobalAlloc）。
 * size == 0 / 非法 align / 耗尽 → NULL；释放必须用 kcore_heap_dealloc 且 (size, align)
 * 逐字一致。Isolated / Sandboxed 不解析该符号（私有分配器 + kcore_memory_acquire/release）。 */
uint8_t *kcore_heap_alloc(size_t size, size_t align);
/* KernelNative 部署后端：归还一次 kcore_heap_alloc（ptr / size / align 必须逐字一致；
 * Layout 驱动 slab / buddy 路由，不得从取整容量反推）。成功 = 0，失败 = -Errno。 */
int32_t kcore_heap_dealloc(uint8_t *ptr, size_t size, size_t align);
/* -- Logging / diagnostics -- */
void kcore_console_write_byte(uint8_t byte);
int32_t kcore_log_line(const uint8_t *ptr, size_t len);
/* -- Machine query -- */
uint32_t kcore_machine_boot_hart(void);
uint32_t kcore_machine_cpu_count(void);
int32_t kcore_machine_has_hart(uint32_t hart_id);
/* -- System query -- */
uint32_t kcore_free_page_count(void);
uint32_t kcore_task_count(void);
uint32_t kcore_component_count(void);
/* -- Component lifecycle -- */
/* Core 侧的最小创建操作：按 artifact 名创建新实例（同一 artifact 允许多实例）。 */
int32_t kcore_component_create(const uint8_t *image_name, size_t image_name_len, uint32_t domain, const struct KcompCreateArgs *args, uint32_t *out_instance);
/* 请求按 domain 部署默认配置的组件。返回 ComponentId raw / -errno；Core 验证并提交，不静默降级。 */
int32_t kcore_component_load(const uint8_t *name, size_t len, uint32_t domain);
/* 请求优雅停止实例，复用 monitor 的 Stop 编排；只支持 KernelNative caller。
 * 需要组件执行身份，IRQ / Gate / policy 上下文拒绝。目标必须 Ready；有未退出 Task、
 * Gate / policy / IRQ 在途执行，或 Native 已发布 Direct 表时返回 EBUSY，拒绝不改状态。
 * 检查与 Stopping 提交共用准入事务；锁外调用 destroy。成功为 Stopped；destroy
 * 失败为 Failed，不重试。没有 Direct release 协议，因此拒绝销毁已暴露 ctx 的实例。
 * KernelNative 是受信部署，本操作不引入跨组件管理权限或父子 owner 账本。 */
int32_t kcore_component_stop(uint32_t component);
/* -- Task control -- */
/* 创建任务：`entry` 必须落在 caller 组件镜像内；`arg` 原样传给 entry
 * （归属仍来自 Core 执行边界，不是 `arg`）。成功 = `0` 且 TaskId 写入
 * `*out_task`；失败 = `-Errno`。 */
int32_t kcore_task_create(KcompTaskEntry entry, void *arg, uint32_t *out_task);
int32_t kcore_task_start(uint32_t id);
/* 提议将 caller 拥有的 Created 任务启动在逻辑 cpu 上。Core 校验 owner、生命周期与
 * 目标 CPU Online，提交 Runnable 与固定 CPU 归属，再通知目标 CPU。无任务迁移。
 * 普通 kcore_task_start 等价于请求当前 CPU。成功表示任务已提交，不保证已经执行。 */
int32_t kcore_task_start_on(uint32_t id, uint32_t cpu);
/* -- Machine query -- */
/* 当前执行 CPU 的逻辑身份快照；不授予权限。 */
uint32_t kcore_cpu_current(void);
/* -- Task control -- */
int32_t kcore_task_yield(void);
/* 阻塞当前任务，直到它被 `kcore_task_unpark` 唤醒后再次获得 CPU 才返回。
 * 若已有 pending permit，则消费它并立即返回；否则提交 Blocked 并切走。只能从任务上下文调用。 */
int32_t kcore_task_park(void);
/* 请求唤醒 `id`：目标若为 Blocked，则提交为 Runnable；若为 Created、Runnable 或
 * Running，则记一份 pending permit，下一次 park 消费，重复 permit 合并；Exited 返回
 * `-EINVAL`。不直接切换 CPU。Core 验证 caller 是任务 owner；IRQ 回调可代表其线路
 * owner 调用；相关任务表锁路径必须防止 IRQ 重入死锁。`TaskId` 是 identity，不是权限。
 * 组件自己维护等待队列与条件。 */
int32_t kcore_task_unpark(uint32_t id);
int32_t kcore_task_exit(void);
int32_t kcore_task_state(uint32_t id);
/* -- Panic containment -- */
int32_t kcore_panic_escape(void);
/* -- Scheduler -- */
/* 把 CPU 交给调度器：propose（调用已选择的策略）→ validate → commit → switch 全在
 * Core；跑完所有 Runnable 任务后返回（锚点上下文）。无 Runnable 任务时为 no-op。
 * **从未选择过策略** → `-ENOTSUP`（`NoPolicy`，绝不退化到内置调度器）；已安装策略
 * 失败 / 失效后 Core 用确定性回退（id 序首项）继续调度，不会变成 `NoPolicy`。 */
int32_t kcore_sched_run(void);
/* 选择调度策略 endpoint（只提交 EndpointId，不发布）。Core 校验 contract + abi +
 * 存活 + dispatcher；IRQ / service-call / policy 执行上下文内拒绝。 */
int32_t kcore_sched_set_policy(uint64_t endpoint);
/* -- Device ownership / MMIO（mechanism-first：claim 后直接拿 MMIO 指针） -- */
/* 纯发现：compatible 为空（非 NULL 指针，len = 0）时枚举全部设备；否则按 compatible 过滤。只返回 DeviceId，非权限。 */
int32_t kcore_device_nth(const uint8_t *compatible, size_t len, uint32_t ordinal, uint32_t *out_device_id);
/* 按 DeviceId 复制 DeviceInfo 与 primary compatible（完整、不截断、无 NUL）。
 * 调用方提供互不重叠的可写 out 和 compatible 缓冲区，out 无对齐要求。
 * 成功 0；不存在设备 -ENOENT、机器尚未提交 -ENODEV、空指针 -EFAULT、
 * 容量不足 -ENOBUFS、计数无法表示 -EOVERFLOW。失败不写任何输出。
 * DeviceId 0 合法；只读观察不 claim / release，不触碰 MMIO / IRQ / DMA。 */
int32_t kcore_device_info(uint32_t device_id, struct KcoreDeviceInfo *out, uint8_t *compatible, size_t capacity);
/* 认领确切设备：Core 记 owner，返回本执行域下的 MMIO 指针 + 长度。 */
int32_t kcore_device_claim(uint32_t device_id, uint8_t **out_mmio, size_t *out_len);
int32_t kcore_device_release(uint32_t device_id);
/* -- IRQ routes（锚点是 (DeviceId, resource_index)；只支持 native callback） -- */
/* 注册该设备某条中断资源的投递目标（resource_index = interrupts 下标）；
 * 同一逻辑线换 key 重复注册 = -EBUSY。 */
int32_t kcore_irq_register(uint32_t device_id, uint32_t resource_index, IrqHandler handler, void *ctx);
/* 使能该设备某条中断资源（先验证 route，再配置中断控制器）。
 * 成功 = 0；失败 = `-Errno`（`ENODEV` 设备/资源不存在或未绑定线 /
 * `EACCES` 非 owner / `EINVAL` 尚未注册 handler）。 */
int32_t kcore_irq_enable(uint32_t device_id, uint32_t resource_index);
int32_t kcore_irq_disable(uint32_t device_id, uint32_t resource_index);
/* 撤销该设备某条中断资源的 route 并关断控制器线——此后不再投递给已死 owner。 */
int32_t kcore_irq_release(uint32_t device_id, uint32_t resource_index);
/* -- DMA（allocation 与 mapping 分离） -- */
/* 分配 CPU-visible、物理连续的 DMA 缓冲（device-agnostic）。 */
int32_t kcore_dma_alloc(size_t size, uint8_t **out_ptr, size_t *out_len);
/* 释放一段 DMA 缓冲（backing 进 Core quarantine，不立即 free）。 */
int32_t kcore_dma_free(uint8_t *ptr);
/* 把 buffer 映射给设备：设备可见地址 + mapping id（No-IOMMU identity）。 */
int32_t kcore_dma_map(uint32_t device_id, uint8_t *ptr, size_t len, int32_t direction, uint64_t *out_device_addr, uint64_t *out_mapping);
int32_t kcore_dma_unmap(uint64_t mapping);
/* -- Component endpoints（Contract / Endpoint） -- */
/* 发布 endpoint（staged：init 期间只记录 pending；create 返回 0 后 Core 原子提交）。
 * provider 由当前 create 上下文解析，不信任组件自报身份；返回 0 不返回 EndpointId。
 * api/ctx 是 Direct 的 function table + state（Core 只存不解引用）；port 服务 Gate。 */
int32_t kcore_endpoint_publish(const uint8_t *port_name, size_t port_name_len, uint64_t contract, uint32_t kind, uint64_t abi, uint32_t port, const void *api, void *ctx);
/* 按 (provider, port_name, contract) 发现 endpoint：只校验 contract + 存活，
 * **不校验 abi**（id 是 opaque capability，abi 用 kcore_endpoint_validate 核对）。
 * 成功写 EndpointId 到 *out_endpoint；失败返回 -Errno。 */
int32_t kcore_endpoint_lookup(uint32_t provider, const uint8_t *port_name, size_t port_name_len, uint64_t contract, uint64_t *out_endpoint);
/* 只读校验端点：contract + abi exact-match + 存活（lookup）。无副作用；
 * 成功 = 0，失败 = -Errno（EINVAL 契约/ABI 不符；ENOENT 死端点；ENODEV provider 消失）。 */
int32_t kcore_endpoint_validate(uint64_t endpoint, uint64_t contract, uint64_t abi);
/* bind 时由 Core 选定机制（一次）：校验 contract+abi exact-match + 存活后，同域
 * KernelNative → DIRECT（写 out_api / out_ctx）；否则 → GATE（不写 api/ctx，改用
 * kcore_endpoint_call）。不支持的组合返回 -ENOTSUP，绝不静默降级；无组件执行边界
 * 返回 -EPERM。 */
int32_t kcore_endpoint_bind(uint64_t endpoint, uint64_t contract, uint64_t abi, uint32_t *out_mechanism, size_t *out_api, size_t *out_ctx);
/* 调用 endpoint。返回 Core 传输状态（0 / -Errno）；provider 自己的 i32 返回写入
 * *out_status（仅传输返回 0 时有意义）。dispatcher 在 Core 控制的 service 边界内
 * 执行（provider 域内栈 / principal / re-entry 与 IRQ 门禁 / panic containment）。
 * K/I caller 均支持；I 出站经 Core 栈/root 桥接与扁平缓冲搬运。Sandbox 未实现。 */
int32_t kcore_endpoint_call(uint64_t endpoint, uint32_t method, const uint8_t *args, size_t args_len, const uint8_t *input, size_t input_len, uint8_t *output, size_t output_len, int32_t *out_status);
/* -- Console / observation -- */
/* 轮询诊断 console。字节 0..255；无输入 -EAGAIN。无输入时做一次有界 idle 等待，caller 可 yield 后重试。 */
int32_t kcore_console_read_byte(void);
/* 按 ordinal 复制组件状态与完整名字（不含 NUL）。ENOENT = 枚举完；ENOBUFS = 名字缓冲不足（不截断）。逐次读取，不保证全表原子快照。 */
int32_t kcore_component_nth(uint32_t ordinal, struct kcore_component_info *out, uint8_t *name, size_t capacity);
/* 按 ordinal 复制已提交 endpoint（含 Invalid）与完整端口名。ENOENT = 枚举完；ENOBUFS = 名字缓冲不足。不交付 api/ctx。 */
int32_t kcore_endpoint_nth(uint32_t ordinal, struct kcore_endpoint_info *out, uint8_t *name, size_t capacity);
/* -- User task execution -- */
/* Create an unstarted task and private user AS; caller owns it. RV64 supervisor/MMU only; other profiles return ENOTSUP. */
int32_t kcore_user_create(KcompTaskEntry entry, void *arg, uint32_t *out_task);
/* Map zeroed private backing. Page-aligned low VA; R=1 W=2 X=4; W^X. RV64 supervisor/MMU only; other profiles return ENOTSUP. */
int32_t kcore_user_map(uint32_t task, uint64_t address, uint64_t len, uint32_t permission);
/* Atomically replace permissions of a fully mapped user range; private AS and W^X checks remain in Core. */
int32_t kcore_user_protect(uint32_t task, uint64_t address, uint64_t len, uint32_t permission);
/* Initialize user mappings only before task start; kernel aliases, never SUM. RV64 supervisor/MMU only; other profiles return ENOTSUP. */
int32_t kcore_user_load(uint32_t task, uint64_t address, const uint8_t *buffer, size_t len);
/* Copy from actual user mappings after whole-range validation. RV64 supervisor/MMU only; other profiles return ENOTSUP. */
int32_t kcore_user_read(uint32_t task, uint64_t address, uint8_t *buffer, size_t len);
/* Copy to writable user mappings after whole-range validation. RV64 supervisor/MMU only; other profiles return ENOTSUP. */
int32_t kcore_user_write(uint32_t task, uint64_t address, const uint8_t *buffer, size_t len);
/* Validate U RX entry and RW-NX aligned stack; initialize registers. RV64 supervisor/MMU only; other profiles return ENOTSUP. */
int32_t kcore_user_prepare(uint32_t task, uint64_t pc, uint64_t sp);
/* Enter current task in U-mode until ecall/fault/interrupt, bounded by a caller-proposed absolute timer deadline. No lock or scheduling on trap stack. RV64 supervisor/MMU only; other profiles return ENOTSUP. */
int32_t kcore_user_step(int64_t result, uint64_t deadline, struct kcore_user_trap *out);
/* Deep-copy current suspended user AS/registers to an unstarted task; no PID semantics. RV64 supervisor/MMU only; other profiles return ENOTSUP. */
int32_t kcore_user_clone(KcompTaskEntry entry, void *arg, uint32_t *out_task);
/* Atomically replace current user context with an unstarted prepared task; no exec semantics. RV64 supervisor/MMU only; other profiles return ENOTSUP. */
int32_t kcore_user_replace(uint32_t prepared_task);
/* Destroy a never-started task and retire its AS; rollback only. RV64 supervisor/MMU only; other profiles return ENOTSUP. */
int32_t kcore_user_discard(uint32_t task);
/* -- Endpoint Request/Reply -- */
/* 将当前真实 KernelNative Task 注册为本组件 Endpoint 的唯一 Server Task；只接受 owner。 缓冲只借用本次入口；仅可信 KernelNative，私有域暂拒绝；0 / -errno。 */
int32_t kcore_ipc_listen(uint64_t endpoint);
/* Endpoint owner 或 Core 记录的不可变实例创建者明确允许 consumer Component 发送；允许启动锚点编排，拒绝 Gate/IRQ/policy；ID 不是 capability。仅可信 KernelNative，私有域暂拒绝；0 / -errno。 */
int32_t kcore_ipc_grant(uint64_t endpoint, uint32_t consumer);
/* 复制至有界请求槽；每 caller Task 最多一个未收取请求；1024 字节上限。 缓冲只借用本次入口；仅可信 KernelNative，私有域暂拒绝；0 / -errno。 */
int32_t kcore_ipc_submit(uint64_t endpoint, const uint8_t *bytes, size_t len, uint64_t *request);
/* 唯一 Server Task 收取 FIFO 请求及 Core 校验的 consumer 身份；空队列 EAGAIN。 缓冲只借用本次入口；仅可信 KernelNative，私有域暂拒绝；0 / -errno。 */
int32_t kcore_ipc_receive(uint64_t endpoint, uint8_t *bytes, size_t capacity, uint64_t *request, uint32_t *consumer, uint32_t *consumer_task, size_t *length);
/* Server Task 一次性回复；late canceled reply 丢弃并退休 receipt。 缓冲只借用本次入口；仅可信 KernelNative，私有域暂拒绝；0 / -errno。 */
int32_t kcore_ipc_reply(uint64_t request, const uint8_t *bytes, size_t len);
/* caller 一次收取终态；Pending 为 EAGAIN，短缓冲 EMSGSIZE 不消费；completion 为 transport status。 缓冲只借用本次入口；仅可信 KernelNative，私有域暂拒绝；0 / -errno。 */
int32_t kcore_ipc_collect(uint64_t request, uint8_t *bytes, size_t capacity, size_t *length, int32_t *completion);
/* 真实 Task 上原子登记谓词等待后 park；request=0 等 receive，非零等自己请求；醒后复验。 缓冲只借用本次入口；仅可信 KernelNative，私有域暂拒绝；0 / -errno。 */
int32_t kcore_ipc_wait(uint64_t endpoint, uint64_t request);
/* caller 提交 ECANCELED 终态；不撤销已发生的业务副作用；完成后的请求 EALREADY。 缓冲只借用本次入口；仅可信 KernelNative，私有域暂拒绝；0 / -errno。 */
int32_t kcore_ipc_cancel(uint64_t request);
/* owner 永久失效 Endpoint，终结 pending并唤醒；旧 ID 不重定向。 缓冲只借用本次入口；仅可信 KernelNative，私有域暂拒绝；0 / -errno。 */
int32_t kcore_ipc_close(uint64_t endpoint);
/* -- Component identity -- */
/* 返回最内层 Core 执行边界的 ComponentId；身份不是 authority，无组件上下文 EPERM；out 空 EFAULT。 */
int32_t kcore_component_current(uint32_t *out);

/* 接口的稳定名字（publish / bind 必须逐字节一致）。 */
#define KCOMP_BLOCK_DEVICE_NAME "block.device"

/* exact ABI fingerprint：8 字节 ASCII "BLKIPCRO" 的大端读数。 */
#define KCOMP_BLOCK_DEVICE_ABI UINT64_C(0x424C4B495043524F)

/* 契约单位：1 sector = 512 字节（`read` / `write` 的 `len` 必须是它的整数倍）。 */
#define KCOMP_BLOCK_DEVICE_SECTOR 512

/* `block.device` 的 endpoint 契约身份（组合策略提供的不透明 `u64`；
 * `kcore_endpoint_lookup` / `kcore_endpoint_validate` 的 `contract` 参数）。
 * 数值 = 8 字节 ASCII tag `b"BLKCONTR"` 的大端读数（与 ABI 指纹同一约定）。 */
#define KCOMP_BLOCK_DEVICE_CONTRACT UINT64_C(0x424C4B434F4E5452)

/* `read` / `write` 的 `args` 区长度：一个 LE `u64` lba（没有其它编码）。 */
#define KCOMP_BLOCK_LBA_LEN 8

/* `capacity` 的 `output` 区长度：一个 LE `u64`（sector 数）。 */
#define KCOMP_BLOCK_CAPACITY_LEN 8

#define KCOMP_BLOCK_METHOD_CAPACITY UINT32_C(0)

#define KCOMP_BLOCK_METHOD_READ UINT32_C(1)

#define KCOMP_BLOCK_METHOD_WRITE UINT32_C(2)

/* filesystem 服务的稳定 endpoint 名字（publish / bind 必须逐字节一致）。 */
#define KCOMP_FILESYSTEM_NAME "filesystem"

/* exact ABI fingerprint（8 字节 ASCII "FSIPCRO1" 的大端读数）。 */
#define KCOMP_FILESYSTEM_ABI UINT64_C(0x4653495043524F31)

/* 第一阶段只读文件访问。flags 是 ABI 编码，不直接暴露 FatFs 的 FA_*。 */
#define KCOMP_FILESYSTEM_OPEN_READ UINT32_C(0x00000001)

/* `filesystem` 的 endpoint 契约身份（组合策略提供的不透明 `u64`；
 * `kcore_endpoint_lookup` / `kcore_endpoint_validate` / `kcore_endpoint_bind` 的
 * `contract` 参数）。数值 = 8 字节 ASCII tag `b"VFSCONTR"` 的大端读数（与 block 的
 * `BLKCONTR` 同一约定）。**契约身份与 ABI 指纹是两个不同的值**：前者标识"哪个
 * endpoint 契约"，后者标识"IPC Wire 协议的逐位布局"。 */
#define KCOMP_FILESYSTEM_CONTRACT UINT64_C(0x564653434F4E5452)

/* `read` / `close` 的 `args` 区与 `open` 的 `output` 区长度：一个 LE `u64` handle（没有其它编码）。 */
#define KCOMP_FILESYSTEM_HANDLE_LEN 8

/* `open` 的 `args` 区长度：一个 LE `u32` flags（没有其它编码）。 */
#define KCOMP_FILESYSTEM_FLAGS_LEN 4

/* `read` 的 `output` 头部长度：一个 LE `u64` 实际读取长度；数据从 offset 8 开始。 */
#define KCOMP_FILESYSTEM_READ_HEADER_LEN 8

/* `open` 的 `input` 上限（**含**结尾 NUL）：provider 用定长 scratch 拷贝路径，超过即 `-EINVAL`。 */
#define KCOMP_FILESYSTEM_PATH_MAX 256

#define KCOMP_FILESYSTEM_NODE_FILE UINT32_C(1)

#define KCOMP_FILESYSTEM_NODE_DIRECTORY UINT32_C(2)

#define KCOMP_FILESYSTEM_LOOKUP_ARGS_LEN 12

#define KCOMP_FILESYSTEM_NAME_MAX 255

/* 原生名字字节；FatFs lookup 当前仅支持 ASCII 8.3，大小写不敏感。 */
#define KCOMP_FILESYSTEM_ENCODING_BYTES UINT32_C(1)

/* LE block EndpointId u64, control ComponentId u32, reserved-zero u32; IPC-only. */
