#define KCOMP_NETWORK_METHOD_TCP_CONNECT UINT32_C(3)

/* args=12：socket + pending_limit；input/output 空。 */
#define KCOMP_NETWORK_METHOD_TCP_LISTEN UINT32_C(4)

/* args=8 socket；input 空；output=8 新 socket。 */
#define KCOMP_NETWORK_METHOD_TCP_ACCEPT UINT32_C(5)

/* args=8 socket；input 空；output=64 status。 */
#define KCOMP_NETWORK_METHOD_TCP_STATUS UINT32_C(6)

/* args=8 socket；input=数据；output=4 实际长度。 */
#define KCOMP_NETWORK_METHOD_TCP_SEND UINT32_C(7)

/* args=8 socket；input 空；output>=8：read + 数据容量。 */
#define KCOMP_NETWORK_METHOD_TCP_RECEIVE UINT32_C(8)

